import { randomBytes } from "node:crypto";

/**
 * Storage keys are generated by the server, never taken from a user. They look like
 *   receipts/2026/11/9f2c...e1.png
 * so a file name chosen by an attacker can never reach the file system.
 */
export type StorageArea = "receipts" | "logos" | "products" | "offers" | "support";

const AREAS: readonly StorageArea[] = ["receipts", "logos", "products", "offers", "support"];
const KEY_PATTERN = /^(receipts|logos|products|offers|support)\/\d{4}\/\d{2}\/[a-f0-9]{32}\.(jpg|png|webp)$/;

export function newObjectKey(area: StorageArea, extension: string, now: Date = new Date()): string {
  if (!AREAS.includes(area)) throw new Error("Unknown storage area");
  if (!/^(jpg|png|webp)$/.test(extension)) throw new Error("Unsupported extension");
  const year = String(now.getUTCFullYear());
  const month = String(now.getUTCMonth() + 1).padStart(2, "0");
  return `${area}/${year}/${month}/${randomBytes(16).toString("hex")}.${extension}`;
}

/** True only for keys this module could have generated. Every read, write and delete checks this first. */
export function isValidObjectKey(key: string): boolean {
  return KEY_PATTERN.test(key);
}
